window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"GtP06obtZaE","speaker":"Nawaf Salam","role":"Head of Government","country":"Lebanon","region":"Middle East","url":"https://www.youtube.com/watch?v=GtP06obtZaE","date":"20260925","title":"🇱🇧 Lebanon - Head of Government Addresses United Nations General Debate, 81st Session | #UNGA","seconds":1246,"words":2543,"counts":{"claims":34,"promises":0,"attacks":0},"topics":[{"topic":"Lebanon sovereignty","share":0.2248,"seconds":280},{"topic":"UN Security Council reform","share":0.1091,"seconds":136},{"topic":"Israel-Lebanon war","share":0.0656,"seconds":82},{"topic":"Iran","share":0.0645,"seconds":80},{"topic":"Lebanon reforms","share":0.0579,"seconds":72},{"topic":"Lebanon reconstruction","share":0.0537,"seconds":67},{"topic":"Lebanon recovery","share":0.0532,"seconds":66},{"topic":"International law","share":0.0525,"seconds":65},{"topic":"UN trust","share":0.0523,"seconds":65},{"topic":"AI governance","share":0.0522,"seconds":65},{"topic":"Economic disparities","share":0.052,"seconds":65},{"topic":"Palestinian refugees","share":0.0516,"seconds":64},{"topic":"UNIFIL withdrawal","share":0.051,"seconds":64},{"topic":"Lebanon economy","share":0.0484,"seconds":60},{"topic":"Ceremony","share":0.011,"seconds":14}],"timeline":[[2,67,"UN trust"],[68,133,"International law"],[135,199,"Economic disparities"],[201,266,"AI governance"],[266,330,"Lebanon sovereignty"],[331,397,"Lebanon recovery"],[399,471,"Lebanon reforms"],[472,533,"Lebanon economy"],[536,599,"Lebanon sovereignty"],[607,689,"Israel-Lebanon war"],[689,781,"Lebanon sovereignty"],[781,845,"UNIFIL withdrawal"],[845,912,"Lebanon reconstruction"],[914,975,"Lebanon sovereignty"],[978,1042,"Palestinian refugees"],[1044,1124,"Iran"],[1127,1195,"UN Security Council reform"],[1196,1264,"UN Security Council reform"],[1264,1278,"Ceremony"]],"stances":{"UN trust":"Nawaf Salam argues that mutual trust is essential for peace, security, and cooperation among states.","International law":"Nawaf Salam argues that international law must be applied universally without selectivity and that restoring trust requires respecting these rules.","Economic disparities":"Nawaf Salam argues that sustainable peace requires a fairer international economic order to address debt servicing costs and climate change impacts on developing nations.","AI governance":"Nawaf Salam argues that international governance must prioritize human rights and privacy in the AI revolution to prevent an AI divide and restore trust.","Lebanon sovereignty":"Nawaf Salam outlines the three core responsibilities of his government: restoring public trust after crises, reasserting state monopoly on force and decision-making, and reclaiming Lebanese territory from Israeli occupation.","Lebanon recovery":"Nawaf Salam asserts that Lebanon's recovery depends on restoring trust in institutions, reclaiming decision-making, and liberating land as a unified cause, while noting the Beirut port explosion must be recalled when discussing trust.","Lebanon reforms":"Nawaf Salam asserts that while the government has not completed all commitments, it is addressing inherited crises and has launched specific reforms without retreating from its duties.","Lebanon economy":"Nawaf Salam states that advancing financial reforms is necessary to restore order, recover depositor funds, and secure an indispensable agreement with the IMF to rebuild international confidence and fund economic recovery.","Israel-Lebanon war":"Nawaf Salam states that Lebanon rejects being used as an arena for others' conflicts and demands an end to the war, a ceasefire, Israeli withdrawal to recognized borders, release of detainees, return of displaced people, and reconstruction.","UNIFIL withdrawal":"Nawaf Salam stresses the need to prevent a security vacuum by establishing a new international force to replace UNIFIL upon its scheduled withdrawal.","Lebanon reconstruction":"Nawaf Salam emphasizes the need for continued international funding to support humanitarian needs, early recovery, and reconstruction in Lebanon, particularly in the south.","Palestinian refugees":"Nawaf Salam argues that cutting funding to UNRWA does not end Palestinian refugee rights and instead worsens their suffering and the burden on host countries like Lebanon.","Iran":"Lebanon expresses solidarity with Arab Gulf states and Jordan against Iranian attacks that threaten regional security, supply chains, and inflation.","UN Security Council reform":"Nawaf Salam argues that the UN Security Council requires immediate reform to include permanent representation for Africa and the Arab world, as its current composition is outdated.","Ceremony":"Nawaf Salam expresses gratitude on behalf of the assembly to the President of the Council of Ministers."},"claims":[{"t":59,"quote":"More than 80 years ago, the United Nations was founded on the promise that the force of law would replace the law of force.","topic":"UN trust","kind":"fact"},{"t":74,"quote":"A world that spends more on armaments than on development.","topic":"International law","kind":"fact"},{"t":81,"quote":"Civilians remain the primary victims while millions face displacement, hunger, and deprivation.","topic":"International law","kind":"fact"},{"t":141,"quote":"some states spend more on servicing their debt than on the health of their citizens and education of their","topic":"Economic disparities","kind":"fact"},{"t":189,"quote":"countries that have contributed least to it bear its gravest consequences","topic":"Economic disparities","kind":"fact"},{"t":202,"quote":"the artificial intelligence revolution is opening unprecedented horizons for progress across every sphere of life","topic":"AI governance","kind":"fact"},{"t":210,"quote":"Yet it also raises challenges for the future of work and for human rights and fundamental freedoms","topic":"AI governance","kind":"fact"},{"t":279,"quote":"We assumed it this responsibility at a time when our country faced three existential challenges.","topic":"Lebanon sovereignty","kind":"fact"},{"t":287,"quote":"The first was to regain the trust of its people after the financial collapse and the Beirut port explosion and the tragedies and wounds they left behind.","topic":"Lebanon sovereignty","kind":"fact"},{"t":304,"quote":"No weapons exist outside its armed forces and no decision on war and peace is taken outside its constitutional institutions.","topic":"Lebanon sovereignty","kind":"fact"},{"t":331,"quote":"Foremost among these is resolution 1701 which remains to this day a fundamental point of reference governing relations between Lebanon and Trust rebuilt, decision-making reclaimed, land liberated.","topic":"Lebanon recovery","kind":"fact"},{"t":392,"quote":"We cannot speak um of restoring trust without recalling the Beirut port explosion.","topic":"Lebanon recovery","kind":"fact"},{"t":399,"quote":"The wound of the 4th of August remains open.","topic":"Lebanon reforms","kind":"fact"},{"t":430,"quote":"paralyzed a public administration of diminished effectiveness, an economy stripped of the foundations of growth, and a state weakened by compounding crisis and by decades of external interference.","topic":"Lebanon reforms","kind":"fact"},{"t":457,"quote":"Lebanon has launched reforms on several fronts, namely revitalizing the public administration, strengthening the independence of the judiciary, modernizing the media law, and abolishing the death penalty.","topic":"Lebanon reforms","kind":"fact"},{"t":472,"quote":"It is also advancing towards the completion of financial reforms aimed at restoring order to the financial system and recovering depositors funds.","topic":"Lebanon economy","kind":"fact"},{"t":488,"quote":"Such an agreement is an indispensable tool for restoring international confidence in Lebanon and a gateway to securing the financing needed from all our regional and international partners for economic recovery and reconstruction.","topic":"Lebanon economy","kind":"fact"},{"t":551,"quote":"decisions taken by the council of ministers notably in August and September of last year and again in March of this year","topic":"Lebanon sovereignty","kind":"fact"},{"t":559,"quote":"Lebanon found itself in a war that it did not choose. It was imposed upon us despite our repeated warnings again","topic":"Lebanon sovereignty","kind":"fact"},{"t":640,"quote":"We want Israel to withdraw from all Lebanese territory up to our internationally recognized borders in accordance with the 199 with the 1949 general armistice agreement and as firmed by resolution 1701.","topic":"Israel-Lebanon war","kind":"fact"},{"t":668,"quote":"It was in that spirit that the Lebanese state entered into negotiations with Israel under the kind opices of the United States of America and its president for which we are grateful","topic":"Israel-Lebanon war","kind":"fact"},{"t":689,"quote":"The sovereignty to which we are committed is indivisible. It requires Israel's withdrawal from all Lebanese territory.","topic":"Lebanon sovereignty","kind":"fact"},{"t":697,"quote":"It equally requires the extension of the authority of the Lebanese state through its own forces over the entirety of its territory with weapons held by the state alone.","topic":"Lebanon sovereignty","kind":"fact"},{"t":781,"quote":"have taken note of security council resolution 2790 of 2025 of 2025 which decided to terminate UNIFIL's operations at the end of this year and to begin its gradual withdrawal","topic":"UNIFIL withdrawal","kind":"fact"},{"t":851,"quote":"The war has left behind a vast humanitarian crisis in Lebanon. It has caused extensive destruction to housing, public facilities, infrastructure, and productive sectors, and has deprived large numbers of Lebanese of their homes and livelihoods.","topic":"Lebanon reconstruction","kind":"fact"},{"t":928,"quote":"We are shouldering our responsibility for reform and for extending the authority of the state over the entirety of our territory.","topic":"Lebanon sovereignty","kind":"fact"},{"t":964,"quote":"there can be no stability in the region as long as this organization remains unable to enable the Palestinian people to exercise their inalienable right to self-determination.","topic":"Lebanon sovereignty","kind":"fact"},{"t":988,"quote":"dozens of resolutions adopted by this assembly and by the security council that lay clear foundations for that right, not to mention the Arab peace initiative","topic":"Palestinian refugees","kind":"fact"},{"t":1018,"quote":"cutting off funding to UNRA or undermining its mandate does not uh end the rights of Palestinian refugees","topic":"Palestinian refugees","kind":"fact"},{"t":1054,"quote":"Iranian attacks that threaten regional security and the freedom and safety of maritime","topic":"Iran","kind":"fact"},{"t":1061,"quote":"The effects of these attacks are not confined to theaters of confrontation. They extend to supply chain, to the prices of goods, particularly food and energy, and to inflation rates.","topic":"Iran","kind":"fact"},{"t":1127,"quote":"The membership of the United Nations has grown nearly four-fold. Colonialism has ended. Africa has risen. Asia has been transformed and new powers have emerged.","topic":"UN Security Council reform","kind":"fact"},{"t":1142,"quote":"Yet the basic composition of the security council remains captive to a historical moment dating back to the end of the Second World War.","topic":"UN Security Council reform","kind":"fact"},{"t":1203,"quote":"calling for an expansion of the security council that achieves more inclusive and equitable Being realists, we do not call for the abolition of the V2. Rather, we call for restraint in its use in cases of genocide, war crimes, crimes against humanity, and serious violations of international humanitarian law.","topic":"UN Security Council reform","kind":"fact"}],"promises":[],"attacks":[],"greece":[],"said":[{"topic":"Lebanon sovereignty","said":0.2248,"reported":0.3,"articles":3},{"topic":"UN Security Council reform","said":0.1091,"reported":0.0,"articles":0},{"topic":"Israel-Lebanon war","said":0.0656,"reported":0.2,"articles":2},{"topic":"Iran","said":0.0645,"reported":0.0,"articles":0},{"topic":"Lebanon reforms","said":0.0579,"reported":0.0,"articles":0},{"topic":"Lebanon reconstruction","said":0.0537,"reported":0.0,"articles":0},{"topic":"Lebanon recovery","said":0.0532,"reported":0.1,"articles":1},{"topic":"International law","said":0.0525,"reported":0.0,"articles":0},{"topic":"UN trust","said":0.0523,"reported":0.1,"articles":1},{"topic":"AI governance","said":0.0522,"reported":0.0,"articles":0},{"topic":"Economic disparities","said":0.052,"reported":0.0,"articles":0},{"topic":"Palestinian refugees","said":0.0516,"reported":0.0,"articles":0},{"topic":"UNIFIL withdrawal","said":0.051,"reported":0.3,"articles":3},{"topic":"Lebanon economy","said":0.0484,"reported":0.0,"articles":0},{"topic":"Ceremony","said":0.011,"reported":0.0,"articles":0}],"pickup":[{"outlet":"Naftemporiki","date":"2026-09-25","title":"Πρωθυπουργός Λιβάνου στον ΟΗΕ: Η ανάκτηση εδαφών από την ισραηλινή κατοχή αποτελεί υπαρξιακή πρόκληση","url":"https://www.naftemporiki.gr/kosmos/2166750/prothypoyrgos-livanoy-ston-oie-i-anaktisi-edafon-apo-tin-israilini-katochi-apotelei-yparxiaki-proklisi","tone":"neutral"},{"outlet":"In.gr","date":"2026-09-25","title":"Ο πρωθυπουργός Σαλάμ ζητά νέα διεθνή δύναμη μετά την αποχώρηση της δύναμης του ΟΗΕ από τον νότιο Λίβανο","url":"https://www.in.gr/2026/09/25/world/o-prothypourgos-salam-zita-nea-diethni-dynami-meta-tin-apoxorisi-tis-dynamis-tou-oie-apo-ton-notio-livano","tone":"neutral"},{"outlet":"Documento","date":"2026-09-25","title":"Πρωθυπουργός Λιβάνου: «Να αποσυρθεί το Ισραήλ απ’ όλα τα εδάφη μας»","url":"https://www.documentonews.gr/article/prothypourgos-livanou-na-aposyrthei-to-israil-ap-ola-ta-edafi-tou-livanou","tone":"neutral"}],"transcript":[{"t":2,"topic":"UN trust","text":"The assembly will hear an address by his excellency Nawaf Salam, president of the Council of Ministers of the Lebanese I request protocol to escort his excellency and invite him to address the &gt;&gt; Mr. Mr. President, Mr. Secretary General, the more I reflect on the theme of this session of the General Assembly, restoring trust and managing transformation, a United Nations that delivers for all, the more convinced I become of the wisdom of that choice. Without mutual trust, peace and security cannot take root among states, nor can cooperation among them flourish. More than 80 years ago, the United Nations was founded on the promise that the force of law would replace the law of force."},{"t":68,"topic":"International law","text":"Yet, we still live in a world of multiplying wars and conflicts. A world that spends more on armaments than on development. Civilians remain the primary victims while millions face displacement, hunger, and deprivation. The problem is not the absence of rules. It is their selective application if not their outright non-application. The sovereignty of states cannot be untouchable in one place and negotiable in another. Nor can the rules of international law apply to some but not to others. Restoring trust requires respect for international law. It requires investment in preventing conflicts before they erupt and in development before poverty and deprivation become a source of violence, extremism and Development too is a matter of peace."},{"t":135,"topic":"Economic disparities","text":"There can be no sustainable peace in a world of widening economic disparities where some states spend more on servicing their debt than on the health of their citizens and education of their This does not absolve developing countries of the responsibility to undertake reform, combat corruption and build institutions. But those efforts require a fairer and more equitable international economic order, one that offers them genuine opportunities to advance. Mr. President, our shared responsibility is equally evident in the face of the profound transformations our world is undergoing. Climate change threatens the lives and livelihoods of millions. countries that have contributed least to it bear its gravest consequences. This calls for equitable adaptation, finance, and technology transfer."},{"t":201,"topic":"AI governance","text":"At the same time, the artificial intelligence revolution is opening unprecedented horizons for progress across every sphere of life. Yet it also raises challenges for the future of work and for human rights and fundamental freedoms. This calls for international governance that places the human being with his or her freedom and privacy at the heart of this transformation. Above all, we must not allow an artificial intelligence divide to emerge on top of the existing gaps in wealth and development. Restoring trust requires that every individual feel that the law protects them, that development do not exclude them, and that progress leaves no one behind. Mr. President, if restoring trust is a challenge facing our world today, for Lebanon, it is not a mere slogan. Just as managing transformation is not an option up for debate together."},{"t":266,"topic":"Lebanon sovereignty","text":"They constitute the very essence of the mission we pledged before our people before our Arab brothers and before the entire world on the day I was entrusted with leading the government of Lebanon. We assumed it this responsibility at a time when our country faced three existential challenges. The first was to regain the trust of its people after the financial collapse and the Beirut port explosion and the tragedies and wounds they left behind. The second was to reclaim its national decision-m so that no authority stands above that of the state. No weapons exist outside its armed forces and no decision on war and peace is taken outside its constitutional institutions. The third was to recover all of its territory from Israeli occupation and to extend its sovereignty over the entirety of its national soil through its own forces in implementation of the ty agreement and insincere respect for the relevant international resolutions on Lebanon."},{"t":331,"topic":"Lebanon recovery","text":"Foremost among these is resolution 1701 which remains to this day a fundamental point of reference governing relations between Lebanon and Trust rebuilt, decision-making reclaimed, land liberated. That is the equation for Lebanon's recovery. These are not three separate challenges. They are three facets of a single cause. Restoring a state that its citizens trust, that is master of its own decisions, and that exercises sovereignty over the whole of its Mr. President, first the trust we seek to restore is not trust in words. It is trust in institutions that protect rights in a judiciary that guarantees justice in an economy that restores prosperity to the people and gives young people the opportunity of a better future. We cannot speak um of restoring trust without recalling the Beirut port explosion."},{"t":399,"topic":"Lebanon reforms","text":"The wound of the 4th of August remains open. It cannot heal without truth, justice and accountability and these will inevitably Some might feel may feel that our government has not yet fulfilled all of its commitments. We do not claim that the task is complete, but fairness demands that we not overlook the scale of legacy we inherited, paralyzed a public administration of diminished effectiveness, an economy stripped of the foundations of growth, and a state weakened by compounding crisis and by decades of external interference. Even though we have not used the difficulty of our circumstances as a pretext to retreat from our commitments and we will not retreat. Lebanon has launched reforms on several fronts, namely revitalizing the public administration, strengthening the independence of the judiciary, modernizing the media law, and abolishing the death penalty."},{"t":472,"topic":"Lebanon economy","text":"It is also advancing towards the completion of financial reforms aimed at restoring order to the financial system and recovering depositors funds. These reforms should pave the way for an agreement with the IMF. Such an agreement is an indispensable tool for restoring international confidence in Lebanon and a gateway to securing the financing needed from all our regional and international partners for economic recovery and reconstruction. Our aim in pursuing reform is not to ask our people to renew their trust in the state. Rather, through reform, we seek to rebuild a state worthy of its people's trust. a state does not regain the trust of its citizens through reform alone, but also by reclaiming its national decision making."},{"t":536,"topic":"Lebanon sovereignty","text":"In that spirit, we did not merely affirm the principle that weapons must be exclusively in the hands of the state and that decisions on war and peace rest solely with its constitutional institutions. We translated that commitment into decisions taken by the council of ministers notably in August and September of last year and again in March of this year. That was after Lebanon found itself in a war that it did not choose. It was imposed upon us despite our repeated warnings again. Repeated warnings of the dangers of being drawn into it. As the war in the region widened and initiatives to end it multiplied, we held fast to a non-negotiable principle. No one speaks for Lebanon and no one negotiates on its behalf except the Lebanese state through its constitutional institutions. It is true that Lebanon is affected by developments in its surroundings."},{"t":607,"topic":"Israel-Lebanon war","text":"&gt;&gt; It is true that Lebanon is affected by developments in its surroundings. That does not mean, however, that we accept it's becoming once again an arena for the conflicts of others or a burning chip bargaining chip in their hands. Lebanon's future will not be decided on its behalf, nor may its security and stability become the price of settlements concluded in its absence. Third, our position on the war has been clear from the outset. We want it to end. We want the ceasefire consolidated. We want Israel to withdraw from all Lebanese territory up to our internationally recognized borders in accordance with the 199 with the 1949 general armistice agreement and as firmed by resolution 1701. We want the release of all our detinees, the safe and dignified return of our people to their villages and towns and the reconstruction of what the war has It was in that spirit that the Lebanese state entered into negotiations with Israel under the kind opices of the United States of America and its president for which we are grateful with a view to reaching arrangements that ensure an end to the war and the restoration of Lebanon's full sovereignty."},{"t":689,"topic":"Lebanon sovereignty","text":"The sovereignty to which we are committed is indivisible. It requires Israel's withdrawal from all Lebanese territory. It equally requires the extension of the authority of the Lebanese state through its own forces over the entirety of its territory with weapons held by the state alone. It is on these two principles and on the basis of reciprocity and phased implementation that the tripartite framework reached in the negotiations rest. However, the success of any agreement is measured not by declared intentions but by fulfillment of commitments. What is required today therefore is to complete the translation of this framework into practical steps within a clear timetable and with a verification mechanism that ensures the implementation of all its Mr. Mr. President, in this context, I must pay tribute to the role played by the United Nations interim force in Lebanon, UNIFIL, and to the courage of its leadership, personnel, and staff, and their sacrifices in preserving stability, supporting the Lebanese armed forces, and implementing resolution To all the countries that have contributed troops to this force, Lebanon extends its profound thanks and We"},{"t":781,"topic":"UNIFIL withdrawal","text":"have taken note of security council resolution 2790 of 2025 of 2025 which decided to terminate UNIFIL's operations at the end of this year and to begin its gradual withdrawal and requested the secretary general to explore available options for the continued implementation of resolution What we wish to stress here and today is the need to avert the vacuum that UNIFIL's withdrawal could create were it to take place without agreement on a new international force to replace Such a force should ensure the continuation of monitoring, reporting and leaison functions and its role should complement the requirements for implementing the tripartite framework. Mr. President, recovering the Mr. President, recovering the land does not mean only the withdrawal of occupying forces."},{"t":845,"topic":"Lebanon reconstruction","text":"It also means the return of its inhabitants and the revival of life in their villages and towns. The war has left behind a vast humanitarian crisis in Lebanon. It has caused extensive destruction to housing, public facilities, infrastructure, and productive sectors, and has deprived large numbers of Lebanese of their homes and livelihoods. While we thank the United Nations entities and our international partners for for their humanitarian contributions, we call at the same time for continued funding to meet the basic needs of those affected, particularly the displaced in parallel with the requirements of early recovery as well as reconstruction and The reconstruction of the south is not merely the rebuilding of stone. It is the rebuilding of people's lives, the restoration of their livelihoods, and the affirmation of the right to live in safety and dignity on their land."},{"t":914,"topic":"Lebanon sovereignty","text":"Mr. President, the Lebanon that stands before you today does not shook its responsibilities, nor does it ask others to do what it is duty bound to do itself. We are shouldering our responsibility for reform and for extending the authority of the state over the entirety of our territory. But we are entitled to ask the international community to shoulder in turn its responsibility to ensure respect for Lebanon sovereignty and the implementation of resolutions of international legitimacy. Mr. President, there can be no lasting stability in Lebanon without lasting stability in our And there can be no stability in the region as long as this organization remains unable to enable the Palestinian people to exercise their inalienable right to self-determination."},{"t":978,"topic":"Palestinian refugees","text":"Like all other peoples of the world, no less and no more. This is despite the dozens of resolutions adopted by this assembly and by the security council that lay clear foundations for that right, not to mention the Arab peace initiative. As for the tragedy of wounded Gaza, it has put the conscience of the world and the import uh inability of its institutions to a test from which there can be no escape. I must stress here that cutting off funding to UNRA or undermining its mandate does not uh end the rights of Palestinian refugees, even if that's what some seek. On the contrary, it compounds their suffering, jeopardizes the prospects for a just and lasting solution to their cause, and increases the burden on host countries, foremost among them Lebanon."},{"t":1044,"topic":"Iran","text":"With regard to the security situation or region, Lebanon wishes to renew its solidarity with the states of the Arab Gulf and with Jordan in the face of Iranian attacks that threaten regional security and the freedom and safety of maritime The effects of these attacks are not confined to theaters of confrontation. They extend to supply chain, to the prices of goods, particularly food and energy, and to inflation rates. Mr. President, allow me to conclude by returning once more to the theme of this session of the General Assembly, restoring trust and managing for United Nations that delivers for The truth is that we cannot call on the states of the world to change their conduct while failing to make the necessary changes within our own organization so that it delivers the results expected of it and regains the trust of the peoples of the The reality is that the world has changed profoundly since 1945."},{"t":1127,"topic":"UN Security Council reform","text":"The membership of the United Nations has grown nearly four-fold. Colonialism has ended. Africa has risen. Asia has been transformed and new powers have emerged. The balance of the global economy has shifted. Yet the basic composition of the security council remains captive to a historical moment dating back to the end of the Second World War. Africa and the Arab world cannot remain without permanent representation on the council, nor can small and medium-sized states remain mere spectators to decisions that concern their security and the f and their future. We know that security council reform is a complex matter. But the difficulty of reform is no argument against its necessity. Indeed, reform of the United Nations must begin here with the security for it is the security council that bears primary responsibility for the maintenance of international peace and security."},{"t":1196,"topic":"UN Security Council reform","text":"are therefore once again add Lebanon's voice to that of the majority of the members of our of our organization in calling for an expansion of the security council that achieves more inclusive and equitable Being realists, we do not call for the abolition of the V2. Rather, we call for restraint in its use in cases of genocide, war crimes, crimes against humanity, and serious violations of international humanitarian law. We insist on reform of the United Nations only because want it to be a more representative, more democratic, and more effective We want an organization true to the purposes and principles of its charter yet ever renewed so that it may rise to the challenges of our rapidly changing world and meet the aspirations of our peoples and their new generations."},{"t":1264,"topic":"Ceremony","text":"I thank you. On behalf of the assembly, I wish to thank the president of the Council of Ministers of the Lebanese Republic."}],"compare":[{"topic":"Lebanon","share":0.2936,"mean":0.0018,"rank":1,"others":6},{"topic":"UN & its reform","share":0.1633,"mean":0.205,"rank":111,"others":170},{"topic":"Iran","share":0.0653,"mean":0.0135,"rank":19,"others":25},{"topic":"International Law & Order","share":0.0531,"mean":0.0604,"rank":84,"others":102},{"topic":"Artificial Intelligence","share":0.0528,"mean":0.0505,"rank":74,"others":83},{"topic":"Global Economy","share":0.0526,"mean":0.0143,"rank":28,"others":31},{"topic":"Israel–Palestine","share":0.0521,"mean":0.0524,"rank":68,"others":76}]};
